import pandas as pd
import matplotlib.pyplot as plt
import numpy as np
from PIL import Image
import tkinter as tk
from tkinter import filedialog, messagebox
import base64
import io

# --- Encoded Field Data ---
# These are shortened for readability in this example. 
# In your actual script, paste the full Base64 strings provided below.
SKILLS_FIELD_B64 = "" 
MATCH_FIELD_B64 = ""

def get_baked_image(is_skills):
    """Decodes the Base64 string back into a PIL Image."""
    img_data = SKILLS_FIELD_B64 if is_skills else MATCH_FIELD_B64
    return Image.open(io.BytesIO(base64.b64decode(img_data)))

def process_data():
    # 1. Get the file path from the dialog
    file_path = filedialog.askopenfilename(
        title="Select TitanReset Log File",
        filetypes=[("Text files", "*.txt")]
    )
    
    if not file_path:
        return  # User cancelled

    # 2. Get the field type from the toggle (Radio Button)
    is_skills = field_var.get()

    try:
        # Load lemlib data
        data = pd.read_csv(file_path, header=None, names=["x", "y", "theta"])
        field_img = get_baked_image(field_var.get() == 1)
        
        FIELD_IN = 144
        fig, ax = plt.subplots(figsize=(7, 7))

        # Draw field
        ax.imshow(field_img, extent=[-FIELD_IN/2, FIELD_IN/2, -FIELD_IN/2, FIELD_IN/2])

        # Plot path
        ax.plot(data["x"], data["y"], "r", linewidth=2, label="Robot Path")
        ax.scatter(data["x"], data["y"], s=4, c="r")

        # Heading arrows
        theta = data["theta"]
        ax.quiver(
            data["x"][::10], data["y"][::10],
            np.cos(theta[::10]), np.sin(theta[::10]),
            scale=45, width=0.004, color="blue", alpha=0.7
        )

        ax.set_aspect('equal')
        ax.set_xlabel("X (inches)")
        ax.set_ylabel("Y (inches)")
        plt.title(f"TitanReset Analysis: {file_path.split('/')[-1]}")
        plt.show()

    except FileNotFoundError:
        messagebox.showerror("Error", f"Could not find image: {img_name}")
    except Exception as e:
        messagebox.showerror("Error", f"Failed to process file:\n{str(e)}")

# --- GUI Setup ---
root = tk.Tk()
root.title("TitanReset Analysis Tool - 38535A")
root.geometry("300x200")

# Instruction Label
tk.Label(root, text="TitanReset Analysis Tool", font=("Arial", 12, "bold")).pack(pady=10)

# Field Toggle (Radio Buttons)
field_var = tk.IntVar(value=0) # Default to Match
tk.Label(root, text="Select Field Type:").pack()
tk.Radiobutton(root, text="Match Field", variable=field_var, value=0).pack()
tk.Radiobutton(root, text="Skills Field", variable=field_var, value=1).pack()

# Action Button
tk.Button(
    root, 
    text="Open Log & Analyze", 
    command=process_data, 
    bg="#ed1c24", # VEX Red
    fg="white", 
    font=("Arial", 10, "bold"),
    pady=10
).pack(pady=20)

root.mainloop()
